import { describe, expect, it } from 'vitest';
import { Perm, PermutationGroup, rational } from '../../src';
import { at, sympyStr } from '../sympy-str';

describe("doctests of sympy.combinatorics.util", () => {
  it("S.schreier_sims()", () => {
    const v1 = PermutationGroup([new Perm([1, 2, 3, 0]), new Perm([1, 0, 2, 3])]);
    v1.schreierSims();
    expect(sympyStr(v1.schreierSims())).toBe('None');
  });
  it("D.schreier_sims()", () => {
    const v1 = PermutationGroup([new Perm([1, 2, 0]), new Perm([2, 1, 0])]);
    v1.schreierSims();
    expect(sympyStr(v1.schreierSims())).toBe('None');
  });
  it("D.strong_gens", () => {
    const v1 = new Perm([1, 2, 0]);
    const v2 = new Perm([2, 1, 0]);
    expect(sympyStr([v1, v2, at(PermutationGroup([v1, v2]).strongGens, 2)])).toBe('[Permutation(0, 1, 2), Permutation(0, 2), Permutation(1, 2)]');
  });
  // a primitive result that no library call returned
  //   D.base
  //   => [0, 1]
  it.todo("D.base");
  it("D.schreier_sims() (2)", () => {
    const v1 = PermutationGroup([new Perm([1, 2, 0]), new Perm([2, 1, 0])]);
    v1.schreierSims();
    expect(sympyStr(v1.schreierSims())).toBe('None');
  });
  it("S.schreier_sims() (2)", () => {
    const v1 = PermutationGroup([new Perm([1, 2, 0]), new Perm([1, 0, 2])]);
    v1.schreierSims();
    expect(sympyStr(v1.schreierSims())).toBe('None');
  });
  it("S.schreier_sims() (3)", () => {
    const v1 = PermutationGroup([new Perm([1, 2, 3, 4, 0]), new Perm([1, 0, 2, 3, 4])]);
    v1.schreierSims();
    expect(sympyStr(v1.schreierSims())).toBe('None');
  });
  it("S.schreier_sims() (4)", () => {
    const v1 = PermutationGroup([new Perm([1, 2, 0]), new Perm([1, 0, 2])]);
    v1.schreierSims();
    expect(sympyStr(v1.schreierSims())).toBe('None');
  });
  it("S.strong_gens", () => {
    const v1 = new Perm([1, 2, 0]);
    const v2 = new Perm([1, 0, 2]);
    expect(sympyStr([v1, v2, at(PermutationGroup([v1, v2]).strongGens, 2)])).toBe('[Permutation(0, 1, 2), Permutation(2)(0, 1), Permutation(1, 2)]');
  });
});

